"""Slice the shipped Cosmyx cube with the Linux x64 AppImage (decision 0147).

The app is run headless (`--slice 0` slices every plate) with a fresh data
folder, and its G-code must look like a real print: the header block with the
"generated by <app> <version> on" line the build writes from version.inc
(SLIC3R_APP_NAME, SoftFever_VERSION), the config block, feature types and at
least min_g1_moves G1 moves.
"""

from __future__ import annotations

import json
import re
import subprocess
from collections.abc import Callable
from pathlib import Path

from .records import Record

Runner = Callable[..., subprocess.CompletedProcess]
APP_NAME = re.compile(r'^\s*set\(\s*SLIC3R_APP_NAME\s+"([^"]*)"\s*\)', re.MULTILINE)
VERSION = re.compile(r'^\s*set\(\s*SoftFever_VERSION\s+"([^"]*)"\s*\)', re.MULTILINE)


def header_identity(version_inc: str) -> tuple[str, str] | None:
    """(SLIC3R_APP_NAME, SoftFever_VERSION) from version.inc text."""
    name, version = APP_NAME.search(version_inc), VERSION.search(version_inc)
    if not name or not version:
        return None
    return name.group(1), version.group(1)


def command(app_run: Path, model: Path, datadir: Path, outputdir: Path, load_settings: list[str],
            xvfb: bool = True) -> list[str]:
    args = [str(app_run), "--datadir", str(datadir), "--outputdir", str(outputdir)]
    if load_settings:
        args += ["--load-settings", ";".join(load_settings)]
    args += ["--slice", "0", str(model)]
    return (["xvfb-run", "-a"] + args) if xvfb else args


def gcode_problems(text: str, app_name: str, version: str, min_g1: int) -> list[str]:
    problems = []
    if "; HEADER_BLOCK_START" not in text:
        problems.append("no '; HEADER_BLOCK_START'")
    if not re.search(rf"^; generated by {re.escape(app_name)} {re.escape(version)} on ", text, re.MULTILINE):
        problems.append(f"no '; generated by {app_name} {version} on' line")
    if "; CONFIG_BLOCK_START" not in text:
        problems.append("no '; CONFIG_BLOCK_START'")
    if ";TYPE:" not in text:
        problems.append("no ';TYPE:' feature marker")
    moves = len(re.findall(r"^G1 ", text, re.MULTILINE))
    if moves < min_g1:
        problems.append(f"{moves} G1 moves, expected at least {min_g1}")
    return problems


def output_problems(outputdir: Path, app_name: str, version: str, min_g1: int) -> tuple[list[str], dict]:
    problems, details = [], {}
    result = outputdir / "result.json"
    if result.is_file():
        try:
            code = json.loads(result.read_text(encoding="utf-8")).get("return_code")
        except ValueError:
            code = "unreadable"
        details["return_code"] = code
        if code != 0:
            problems.append(f"result.json return_code {code}")
    plates = sorted(outputdir.glob("plate_*.gcode"))
    details["plates"] = [p.name for p in plates]
    if not plates:
        problems.append("no plate_*.gcode written")
    for plate in plates:
        for problem in gcode_problems(plate.read_text(encoding="utf-8", errors="replace"), app_name, version, min_g1):
            problems.append(f"{plate.name}: {problem}")
    return problems, details


def run_slice(artifact: str, app_run: Path, resources: Path, subject: Path, work: Path, expectations: dict,
              run: Runner = subprocess.run, xvfb: bool = True) -> Record:
    settings = expectations["slice"]
    model = resources / settings["model"]
    if not model.is_file():
        return Record("linux", artifact, settings["model"], "slice", "skip", "T5 not merged: the model is not shipped")
    version_inc = subject / "version.inc"
    identity = header_identity(version_inc.read_text(encoding="utf-8")) if version_inc.is_file() else None
    if identity is None:
        return Record("linux", artifact, "", "slice", "fail", "version.inc of the built commit has no app name or version")
    datadir, outputdir = work / "slice-data", work / "slice-out"
    datadir.mkdir(parents=True, exist_ok=True)
    outputdir.mkdir(parents=True, exist_ok=True)
    args = command(app_run, model, datadir, outputdir, settings.get("load_settings", []), xvfb)
    timeout = expectations["linux"]["slice_timeout"]
    try:
        done = run(args, capture_output=True, text=True, errors="replace", check=False, timeout=timeout)
    except subprocess.TimeoutExpired:
        return Record("linux", artifact, settings["model"], "slice", "fail", f"slicing took more than {timeout} s")
    problems, details = output_problems(outputdir, identity[0], identity[1], settings["min_g1_moves"])
    details["exit"] = done.returncode
    if problems:
        tail = (done.stderr or done.stdout or "").strip().splitlines()[-3:]
        details["tail"] = tail
        return Record("linux", artifact, settings["model"], "slice", "fail", "; ".join(problems[:5]), details)
    return Record("linux", artifact, settings["model"], "slice", "pass",
                  f"{len(details['plates'])} plate(s) sliced", details)
